mapper.select:
with recursive selected_menu as ( select distinct menu.id, menu.parent_id, menu.label, menu.icon, menu.path, menu.hidden, menu.sort_order from dp_menu menu join dp_role_menu relation on relation.menu_id = menu.id join dp_role role on role.id = relation.role_id where role.status = 1 and role.deleted = 0 and menu.deleted = 0
and role.baseline_role_id in
#{roleId}
and 1 = 0
), menu_tree as ( select id, parent_id, label, icon, path, hidden, sort_order from selected_menu union select parent.id, parent.parent_id, parent.label, parent.icon, parent.path, parent.hidden, parent.sort_order from dp_menu parent join menu_tree child on child.parent_id = parent.id where parent.deleted = 0 ) select distinct id, parent_id, label, icon, path, hidden, sort_order from menu_tree order by parent_id, sort_order, id
